import { MakeLogicType, afterMount, connect, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { signalsScoutConfigToolCatalogue } from 'products/signals/frontend/generated/api'
import type { ScoutToolCatalogueApi } from 'products/signals/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scoutToolCatalogueLogicValues {
    currentTeamId: number | null // teamLogic
    catalogue: ScoutToolCatalogueApi | null
    catalogueFailed: boolean
    catalogueLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scoutToolCatalogueLogicActions {
    loadCatalogue: () => any
    loadCatalogueFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCatalogueSuccess: (
        catalogue: ScoutToolCatalogueApi | null,
        payload?: any
    ) => {
        catalogue: ScoutToolCatalogueApi | null
        payload?: any
    }
}

export type scoutToolCatalogueLogicType = MakeLogicType<scoutToolCatalogueLogicValues, scoutToolCatalogueLogicActions>

/**
 * The MCP tool catalogue the scout tool picker reads. It is the same for every project and changes
 * only with a deploy, so one load per mount is enough.
 */
export const scoutToolCatalogueLogic = kea<scoutToolCatalogueLogicType>([
    path(['products', 'signals', 'inbox', 'logics', 'scoutToolCatalogueLogic']),
    connect({
        values: [teamLogic, ['currentTeamId']],
    }),
    loaders(({ values }) => ({
        catalogue: [
            null as ScoutToolCatalogueApi | null,
            {
                loadCatalogue: async () => {
                    if (values.currentTeamId === null) {
                        return null
                    }
                    return await signalsScoutConfigToolCatalogue(String(values.currentTeamId))
                },
            },
        ],
    })),
    reducers({
        catalogueFailed: [
            false,
            {
                loadCatalogue: () => false,
                loadCatalogueSuccess: () => false,
                loadCatalogueFailure: () => true,
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadCatalogue()
    }),
])
